SELECT CASE WHEN c.credit_limit >= 15900 THEN 'high' WHEN c.credit_limit >= 6400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, c.segment, ROUND(AVG(t.amount), 2) AS avg_amount, SUM(CASE WHEN t.txn_type = 'REFUND' THEN 1 ELSE 0 END) AS refund_count FROM transactions t LEFT JOIN accounts a ON t.account_id = a.id LEFT JOIN customers c ON a.customer_id = c.id WHERE c.age BETWEEN 40 AND 45 GROUP BY CASE WHEN c.credit_limit >= 15900 THEN 'high' WHEN c.credit_limit >= 6400 THEN 'mid' ELSE 'low' END, c.segment HAVING ROUND(AVG(t.amount), 2) > 56;
